# Critical Rhino for fzf.
# Generated by scripts/build_fzf.py; don't edit by hand.
#
# fzf can't tell a dark terminal from a light one, so every color is one of the
# terminal's 16 or its own, and switches with the terminal. The current line is the
# editors' blue band, drawn in reverse video so it reads in both.
#
# Source it from ~/.bashrc, before fzf's key bindings:
#   . ~/path/to/critical-rhino/extras/fzf/critical-rhino.sh

export FZF_DEFAULT_OPTS="${FZF_DEFAULT_OPTS:+$FZF_DEFAULT_OPTS }--color=16,fg:-1,bg:-1,hl:blue,fg+:blue:regular:reverse,bg+:-1,hl+:blue:reverse:bold,gutter:-1,pointer:blue,marker:magenta,query:-1,disabled:white,prompt:blue,info:white,spinner:yellow,header:cyan,label:white,border:bright-black,separator:bright-black,scrollbar:bright-black,preview-fg:-1,preview-bg:-1,preview-border:bright-black,preview-scrollbar:bright-black,preview-label:white"
